en.nethack.quest.common.test_pattern.text:
{quest_player_name}:	return(plname);
 {quest_role_name}:	return(pl_character);
 {quest_current_rank}:	return((char *)rank_of(u.ulevel));
 {quest_minimum_quest_rank}:	return((char *)rank_of(MIN_QUEST_LEVEL));
 {quest_sibling_term}:	return((flags.female) ? "sister" : "brother" );
 {quest_child_term}:	return((flags.female) ? "daughter" : "son" );
 {quest_quest_leader}:	return((char *)ldrname());
 {quest_intermediate_destination}:	return(intermed());
 {quest_quest_artifact}:	return(artiname());
 {quest_short_quest_artifact}:	return(shortened(artiname()));
 {quest_quest_nemesis}:	return((char *)neminame());
 {quest_quest_guardian}:	return((char *)guardname());
 {quest_alignment_title}:	return((char *)align_gtitle(u.ualignbase[1]));
 {quest_quest_home}:	return((char *)homebase());
 {quest_original_alignment}:	return(Alignnam(u.ualignbase[1]));
 {quest_current_alignment}:	return(Alignnam(u.ualign.type));
 {quest_original_alignment_deity}:	return((char *)align_gname(u.ualignbase[1]));
 {quest_lawful_deity}:	return((char *)align_gname(A_LAWFUL));
 {quest_chaotic_alignment}:	return("chaotic");
 {quest_neutral_alignment}:	return("neutral");
 {quest_lawful_alignment}:	return("lawful");
 {quest_perception_verb}:	return((Blind) ? "sense" : "see");
 {quest_dungeon_name}:	return("The Dungeons of Doom");
 %:	return(percent_sign);
 a suffix:	return an(root);
 A suffix:	return An(root);
 C suffix:	return capitalized(root);
 h suffix:	return pronoun(he_or_she, mon_of(root)); /* for {quest_quest_leader},{quest_quest_nemesis},{quest_original_alignment_deity},{quest_quest_artifact} */
 H suffix:	return capitalized(pronoun(he_or_she, mon_of(root)));
 i suffix:	return pronoun(him_or_her, mon_of(root));
 I suffix:	return capitalized(pronoun(him_or_her, mon_of(root)));
 j suffix:	return pronoun(his_or_her, mon_of(root));
 J suffix:	return capitalized(pronoun(his_or_her, mon_of(root)));
 p suffix:	return makeplural(root);
 P suffix:	return makeplural(capitalized(root));
 s suffix:	return s_suffix(root);
 S suffix:	return s_suffix(capitalized(root));
 t suffix:	return strip_the_prefix(root);

en.nethack.quest.rog.assignquest.text:
"Will everyone not going to retrieve {quest_quest_artifact} from that
jerk, {quest_quest_nemesis}, take one step backwards.  Good choice,
{quest_player_name}, because I was going to send you anyway.  My other {quest_quest_guardian_modifier_p}
are too valuable to me.

"Here's the deal.  I want {quest_quest_artifact}, {quest_quest_nemesis}
has {quest_quest_artifact}.  You are going to get {quest_quest_artifact}
and bring it back to me.  So simple an assignment even you can understand
it."

ja.nethack.quest.rog.badlevel.text:
「現時点で{quest_current_rank}を極めたか？俺は10年前に{quest_minimum_quest_rank}を極めたものだ．
  私は{quest_minimum_quest_rank}を極めた１人として送られたのだが，それに比べて{quest_player_name}
  お前はどうだ？ふん．忘れるな！俺はお前を殺そうとしてるのだぜ．」

ja.nethack.quest.val.badlevel.text:
「{quest_player_name}よ，私はあなたと{quest_quest_nemesis}の戦いを見ています．しかし
  あなたは準備ができてないようです．今のままではあなたは{quest_quest_nemesis}
  の手により殺されてしまうでしょう．いけません．こんなことになっては
  いけない．戻りなさい，そして戦いにより経験を積むのです．{quest_minimum_quest_rank}
  になってから戻ってくるのです．そうすれば，{quest_quest_nemesis}を打ち負かすこ
  とができるでしょう．」
